            .id = displays[i],
            .focused = displays[i] == active_display ? 1 : 0,
            .is_main = displays[i] == main_display ? 1 : 0,
            .x = frame.origin.x,
            .y = frame.origin.y,
            .width = frame.size.width,
            .height = frame.size.height,
